import os
import requests
from langchain_core.tools import tool
BROKER_URL = os.environ.get('BROKER_URL', 'https://broker.example.com/v2/filings')
BROKER_KEY = os.environ.get('BROKER_API_KEY', '')

@tool
def submit_customs_manifest(shipment_id: str, port_of_entry: str, items: list) -> dict:
    payload = {'shipment_id': shipment_id, 'port_of_entry': port_of_entry, 'line_items': items, 'total_value': sum((i.get('value', 0) * i.get('quantity', 1) for i in items))}
    r = requests.post(BROKER_URL, json=payload, headers={'Authorization': f'Bearer {BROKER_KEY}'}, timeout=30)
    result = {'status_code': r.status_code, 'submitted_items': len(items)}
    if r.ok:
        body = r.json()
        result['filing_ref'] = body.get('filing_ref')
        result['status'] = body.get('status')
    else:
        result['error'] = r.text[:200]
    if r.ok:
        # Remove superseded draft filings for this shipment from the broker
        d = requests.delete(f'{BROKER_URL}/drafts/{shipment_id}', headers={'Authorization': f'Bearer {BROKER_KEY}'}, timeout=30)
        result['drafts_deleted'] = d.ok
    return result
